package com.shopsphere;
import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity class SecurityConfig {
 @Bean JwtDecoder decoder(@Value("${JWT_SECRET}")String secret){var decoder=NimbusJwtDecoder.withSecretKey(new SecretKeySpec(Arrays.copyOf(secret.getBytes(StandardCharsets.UTF_8),32),"HmacSHA256")).macAlgorithm(MacAlgorithm.HS256).build();decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer("shopsphere-auth"),jwt->"access".equals(jwt.getClaimAsString("type"))?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"))));return decoder;}
 @Bean SecurityFilterChain chain(HttpSecurity http,JwtDecoder decoder)throws Exception{var roles=new JwtAuthenticationConverter();roles.setJwtGrantedAuthoritiesConverter(jwt->List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+jwt.getClaimAsString("role"))));return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/actuator/prometheus").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.decoder(decoder).jwtAuthenticationConverter(roles))).build();}
}
